CREATE TABLE IF NOT EXISTS {fq}.`gold_copper_recovery_schedule` (
  `wire_center_id` STRING COMMENT 'Unique wire center identifier. FK to gold_wire_center_scorecard.',
  `wire_center_name` STRING COMMENT 'Human-readable wire center name for display and reporting.',
  `state_code` STRING COMMENT 'US state abbreviation. Legacy copper states: CO, MN, WA, OR, ID, AZ.',
  `assigned_wave` STRING COMMENT 'Optimized retirement wave assignment (YYYY-QN format). Output of LP/MIP solver.',
  `wave_year` BIGINT COMMENT 'Year component of assigned_wave (e.g. 2026). For time-series aggregation.',
  `wave_quarter` BIGINT COMMENT 'Quarter component of assigned_wave (1-4). For time-series aggregation.',
  `wave_start_date` STRING COMMENT 'Calendar start date of the assigned retirement wave (first day of the quarter).',
  `fiber_ready` BOOLEAN COMMENT 'TRUE if fiber overbuild is complete at this wire center. Required before copper retirement.',
  `puc_filing_required` BOOLEAN COMMENT 'TRUE if state PUC filing is required before retirement. Adds regulatory lead time.',
  `copper_device_count` BIGINT COMMENT 'Count of copper devices (CPE, ONT, OLT, patch_panel) at this wire center.',
  `estimated_crew_days` BIGINT COMMENT 'Estimated crew-days needed to decommission this wire center (5 days/device).',
  `retirement_readiness_score` DOUBLE COMMENT 'Composite 0-100 readiness score. Higher = more ready to retire.',
  `retirement_priority_rank` BIGINT COMMENT 'Priority rank across all wire centers (1 = retire first).',
  `affected_customer_count` BIGINT COMMENT 'Count of distinct customers served by copper at this wire center.',
  `annual_revenue_at_risk` DOUBLE COMMENT 'Annual recurring revenue (USD) from copper-dependent services at this wire center.',
  `salvage_device_count` BIGINT COMMENT 'Count of copper devices eligible for salvage at this wire center.',
  `total_device_weight_kg` DOUBLE COMMENT 'Total weight (kg) of salvageable copper devices. From device weight inventory.',
  `estimated_copper_weight_kg` DOUBLE COMMENT 'Estimated recoverable copper weight (kg). Copper content = 30pct of device weight.',
  `estimated_copper_weight_tons` DOUBLE COMMENT 'Estimated recoverable copper weight in metric tons.',
  `wave_lme_price_usd_ton` DOUBLE COMMENT 'London Metal Exchange copper price forecast (USD/metric ton) for this wave period.',
  `wave_comex_price_usd_lb` DOUBLE COMMENT 'COMEX copper futures price forecast (USD/lb) for this wave period.',
  `wave_labor_cost_index` DOUBLE COMMENT 'Bureau of Labor Statistics labor cost index forecast for this wave period. Base year = 1.0.',
  `wave_material_cost_index` DOUBLE COMMENT 'Producer Price Index forecast for materials in this wave period. Base year = 1.0.',
  `gross_salvage_revenue_usd` DOUBLE COMMENT 'Projected gross revenue from copper salvage: copper_weight_tons × LME_price × 85pct recovery rate.',
  `estimated_decommission_cost_usd` DOUBLE COMMENT 'Estimated decommission labor + material cost, adjusted for wave-period cost indices.',
  `net_salvage_value_usd` DOUBLE COMMENT 'Net salvage value = gross_salvage_revenue - estimated_decommission_cost. Positive = profitable salvage.',
  `salvage_timing_signal` STRING COMMENT 'Market timing recommendation: favorable (high prices, low costs), neutral, or unfavorable. Guides wave sequencing.',
  `generated_at` TIMESTAMP COMMENT 'UTC timestamp when this forecast row was generated.'
) USING DELTA
COMMENT 'SYNTHETIC DATA — Gold-layer copper salvage volume and revenue forecast by retirement wave. Joins wave schedule, device weight inventory, and commodity price forecasts to project net salvage value per wire center. Copper content estimated at 30pct of device weight with 85pct market recovery rate. Created by @data-analyst.'